-- ----------------------------
-- Table structure for ai_model_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_model_config`;
CREATE TABLE `ai_model_config` (
  `id` bigint NOT NULL COMMENT '主键ID(雪花ID)',
  `tenant_id` varchar(20) DEFAULT '' COMMENT '租户ID，多租户',
  `config_name` varchar(100) NOT NULL COMMENT '配置名称，如DeepSeek-考试主模型',
  `model_type` varchar(50) NOT NULL COMMENT '模型类型：OPENAI/DEEPSEEK/QWEN/DOUBAO/CUSTOM',
  `model_name` varchar(100) NOT NULL COMMENT '模型名称，如deepseek-chat',
  `api_base` varchar(255) DEFAULT NULL COMMENT 'API接口地址',
  `api_key` varchar(512) DEFAULT NULL COMMENT 'API密钥（加密存储！不要明文）',
  `temperature` decimal(3,2) DEFAULT '0.70' COMMENT '温度，0~1',
  `max_tokens` int DEFAULT '2048' COMMENT '最大输出token',
  `timeout` int DEFAULT '60000' COMMENT '请求超时时间(ms)',
  `retry_count` tinyint DEFAULT '1' COMMENT '失败重试次数（单个实例重试）',
  `priority` int DEFAULT '10' COMMENT '优先级，数字越小优先级越高，故障切换优先选高优先级',
  `weight` int DEFAULT '100' COMMENT '权重，同优先级下负载均衡权重',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态：0禁用，1启用',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注说明',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记 0正常 1删除',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `create_dept` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tenant_status` (`tenant_id`,`status`,`del_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI大模型配置表';

-- ----------------------------
-- Records of ai_model_config
-- ----------------------------
BEGIN;
COMMIT;

